{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "Weights the contribution of model-based and model-free values to determine the net stage-1 action values.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "choice_stickiness",
      "title": "Choice Stickiness",
      "description": "Adds a perseveration bonus to the logits of the stage-1 action chosen on the immediately preceding trial.",
      "params": [
        {
          "name": "rho",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "stickiness = np.zeros(2)\n        if last_a1 != -1:\n            stickiness[last_a1] = 1.0\n            \n        logits1 = beta * q_stage1_net + rho * stickiness",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Updates the stage-1 model-free value using the stage-2 reward prediction error scaled by a decay parameter.",
      "params": [
        {
          "name": "lam",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += learning_rate * lam * delta_stage2",
      "expressible_in_slots": true
    }
  ]
}
